import React from "react";
import { useCurrentFrame, useVideoConfig } from "remotion";
import { C, MONO } from "../theme";

type Cap = { start: number; end: number; text: string };

// Generated by tools from voice_build offsets → src/data/captions.gen.json
// eslint-disable-next-line @typescript-eslint/no-var-requires
export const CAPTIONS: Cap[] = require("../data/captions.gen.json");

export const KineticCaptions: React.FC = () => {
  const f = useCurrentFrame();
  const { fps } = useVideoConfig();
  const t = f / fps;
  const cur = CAPTIONS.find((c) => t >= c.start && t < c.end);
  if (!cur) return null;
  const words = cur.text.split(/\s+/);
  const per = (cur.end - cur.start) / words.length;
  const local = t - cur.start;
  const shown = Math.max(1, Math.floor(local / per) + 1);
  return (
    <div
      style={{
        position: "absolute",
        left: 140,
        right: 140,
        bottom: 96,
        display: "flex",
        justifyContent: "center",
      }}
    >
      <div
        style={{
          fontFamily: MONO,
          fontSize: 34,
          lineHeight: 1.5,
          color: C.ink,
          background: "rgba(4,8,16,0.78)",
          padding: "14px 26px",
          borderRadius: 8,
          maxWidth: 1500,
          textAlign: "center",
          borderLeft: `3px solid ${C.red}`,
        }}
      >
        {words.map((w, i) => (
          <span key={i} style={{ opacity: i < shown ? 1 : 0.28 }}>
            {w}{" "}
          </span>
        ))}
      </div>
    </div>
  );
};
